calleeMethods:
static inline void task_lock(struct task_struct *p) /* <=== task_lock */ 
{
	spin_lock(&p->alloc_lock);
}

static inline void task_unlock(struct task_struct *p) /* <=== task_unlock */ 
{
	spin_unlock(&p->alloc_lock);
}

